use rivet::{chat::{ChatOptions,Review,Reviewer},budget::BudgetLimits,config::{Project,ProviderConfig},domain::Mode,scheduler};
use serde_json::{Value,json};
use std::{path::Path,future::Future,pin::Pin,time::Duration};
use tokio::{net::TcpListener,io::{AsyncReadExt,AsyncWriteExt}};
use tokio_util::sync::CancellationToken;
struct Approved;
impl Reviewer for Approved{fn approve(&mut self,_:Review)->Pin<Box<dyn Future<Output=rivet::error::Result<bool>>+Send+'_>>{Box::pin(async{Ok(true)})}}
async fn cli(root:&Path,args:&[&str])->std::process::Output{tokio::process::Command::new(env!("CARGO_BIN_EXE_rivet")).current_dir(root).env_clear().env("PATH","/usr/bin").args(args).output().await.unwrap()}
#[tokio::test]
async fn template_plan_preview_is_model_free_bound_to_input_and_rejects_links(){
    let temp=tempfile::tempdir_in(Path::new(env!("CARGO_MANIFEST_DIR")).join(".build/tmp")).unwrap();let result=cli(temp.path(),&["run","template","--mode","pair","--task","scoped task"]).await;assert!(result.status.success());std::fs::write(temp.path().join("plan.json"),&result.stdout).unwrap();let preview=cli(temp.path(),&["run","hierarchy","--plan","plan.json"]).await;assert!(preview.status.success());let value:Value=serde_json::from_slice(&preview.stdout).unwrap();assert_eq!(value["executed"],false);assert!(!temp.path().join(".rivet-state").exists());let bad=cli(temp.path(),&["run","hierarchy","--plan","plan.json","--approve","wrong"]).await;assert_eq!(bad.status.code(),Some(3));assert!(!temp.path().join(".rivet-state").exists());std::os::unix::fs::symlink("plan.json",temp.path().join("linked.json")).unwrap();assert!(!cli(temp.path(),&["run","hierarchy","--plan","linked.json"]).await.status.success());assert!(!cli(temp.path(),&["run","template","--mode","pair","--task","scoped task","--minimal"]).await.status.success());
}
async fn request(stream:&mut tokio::net::TcpStream)->Value{let mut b=vec![];let mut part=[0;4096];loop{let n=stream.read(&mut part).await.unwrap();assert!(n>0);b.extend_from_slice(&part[..n]);if let Some(end)=b.windows(4).position(|b|b==b"\r\n\r\n"){let headers=String::from_utf8_lossy(&b[..end]);let size=headers.lines().find_map(|s|s.to_ascii_lowercase().strip_prefix("content-length: ").and_then(|s|s.parse::<usize>().ok())).unwrap();if b.len()>=end+4+size{return serde_json::from_slice(&b[end+4..]).unwrap();}}assert!(b.len()<1024*1024);}}
async fn reply(stream:&mut tokio::net::TcpStream){let body=format!("data: {}\n\ndata: {}\n\ndata: [DONE]\n\n",json!({"choices":[{"index":0,"delta":{"content":"scoped synthetic task complete"},"finish_reason":"stop"}]}),json!({"choices":[],"usage":{"prompt_tokens":10,"completion_tokens":10}}));stream.write_all(format!("HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",body.len()).as_bytes()).await.unwrap();stream.write_all(body.as_bytes()).await.unwrap();}
#[tokio::test]
async fn main_ui_forwards_an_exact_consented_decision_once_without_minting_tool_grants(){
    tokio::time::timeout(Duration::from_secs(20),async{
        let temp=tempfile::tempdir_in(Path::new(env!("CARGO_MANIFEST_DIR")).join(".build/tmp")).unwrap();let project=Project::open(temp.path()).unwrap();let listener=TcpListener::bind("127.0.0.1:0").await.unwrap();let address=listener.local_addr().unwrap();let(waiting,ready)=tokio::sync::oneshot::channel();let(release,proceed)=tokio::sync::oneshot::channel();
        let server=tokio::spawn(async move{let(mut stream,_)=listener.accept().await.unwrap();request(&mut stream).await;waiting.send(()).unwrap();proceed.await.unwrap();reply(&mut stream).await;let(mut stream,_)=listener.accept().await.unwrap();let value=request(&mut stream).await;assert!(value["messages"][0]["content"].as_str().unwrap().contains("role Operator"));assert!(value.to_string().contains("remain within the declared task scope"));assert!(value.to_string().contains("Untrusted evidence"));reply(&mut stream).await;let(mut stream,_)=listener.accept().await.unwrap();request(&mut stream).await;reply(&mut stream).await;});
        let controller=async{ready.await.unwrap();let endpoint:Value=serde_json::from_slice(&std::fs::read(temp.path().join("state/control.json")).unwrap()).unwrap();let run=endpoint["run"].as_str().unwrap();let status=cli(temp.path(),&["run","status",run,"--state-dir","state"]).await;assert!(status.status.success());let status:Value=serde_json::from_slice(&status.stdout).unwrap();let recipient=status["coordination"]["plan"]["agents"].as_array().unwrap().iter().find(|a|a["role"]=="operator").unwrap()["id"].as_str().unwrap();let args=["run","forward",run,"--recipient",recipient,"--scope","current task only","--decision","remain within the declared task scope","--state-dir","state"];let preview=cli(temp.path(),&args).await;assert!(preview.status.success());let preview:Value=serde_json::from_slice(&preview.stdout).unwrap();let digest=preview["review_digest"].as_str().unwrap();let mut approved=args.to_vec();approved.extend(["--approve",digest]);let sent=cli(temp.path(),&approved).await;assert!(sent.status.success());let sent:Value=serde_json::from_slice(&sent.stdout).unwrap();assert_eq!(sent["accepted"],true);assert_eq!(sent["durable"],false);release.send(()).unwrap();};
        let mut reviewer=Approved;let work=rivet::hierarchy::run(&project,Path::new("state"),ProviderConfig{profile:"llama.cpp-compatible".into(),endpoint:format!("http://{address}/v1/chat/completions"),model:"synthetic".into(),context_tokens:Some(65536)},ChatOptions{session:None,task:"scoped synthetic task".into(),steps:10,deadline_seconds:60,budget:BudgetLimits{tokens:100_000,requests:10,cost_micros:0},request_cost_micros:0,credential:None,mcp:vec![],skills:vec![]},scheduler::template(Mode::Pair,"scoped synthetic task",vec![]).unwrap(),&mut reviewer,CancellationToken::new());let(result,())=tokio::join!(work,controller);result.unwrap();server.await.unwrap();let db=rusqlite::Connection::open(temp.path().join("state/ledger.sqlite")).unwrap();let (messages,pending,grants):(i64,i64,i64)=db.query_row("SELECT (SELECT count(*) FROM messages),(SELECT count(*) FROM messages WHERE ack_digest IS NULL),(SELECT count(*) FROM grants)",[],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?))).unwrap();assert_eq!((messages,pending,grants),(2,0,0));
    }).await.unwrap();
}
